content:
{
	"blocks": [
		{
			"type": "section",
			"text": {
				"type": "mrkdwn",
				"text": "${tenant}: *Pipeline* ${incidentMetadata.incidentTitle}"
			}
		},
		{
			"type": "divider"
		},
		{
			"type": "section",
			"text": {
				"type": "mrkdwn",
				"text": "*Start Time:* ${acceldata_dateFormat(incidentMetadata.startedAt)}"
			}
		},
		{
			"type": "section",
			"text": {
				"type": "mrkdwn",
				"text": "*End Time:* ${acceldata_dateFormat(incidentMetadata.finishedAt)}"
			}
		},
		{
			"type": "section",
			"text": {
				"type": "mrkdwn",
				"text": "*Result Status:* ${incidentMetadata.result}"
			}
		},
		{
			"type": "section",
			"text": {
				"type": "mrkdwn",
				"text": "*Warning Events:* ${incidentMetadata.warningEvents}"
			}
		},
		{
			"type": "section",
			"text": {
				"type": "mrkdwn",
				"text": "*Success Events:* ${incidentMetadata.successEvents}"
			}
		},
		{
			"type": "section",
			"text": {
				"type": "mrkdwn",
				"text": "*Error Events:* ${incidentMetadata.errorEvents}"
			}
		},
		{
			"type": "section",
			"text": {
				"type": "mrkdwn",
				"text": "To Check the Execution Details"
			}
		},
		{
			"type": "actions",
			"elements": [
				{
					"type": "button",
					"text": {
						"type": "plain_text",
						"text": "Click Here",
						"emoji": true
					},
					"value": "click_me_123",
					"url": "${link}"
				}
			]
		},
		{
			"type": "divider"
		}
	]
}
